class Solution {
public:
    bool match(string s,string t)
    {
        int n=s.size();
        vector<int> maps(256,-1);
        vector<int> mapt(256,-1);
        for(int i=0;i<n;i++)
        {
            char c1=s[i],c2=t[i];
            if(maps[c2]==-1 and mapt[c1]==-1)
            {
                maps[c2]=c1;
                mapt[c1]=c2;
            }
            else if(!(maps[c2]==c1 and mapt[c1]==c2))
                return false;
        }
        return true;
    }
    vector<string> findAndReplacePattern(vector<string>& words, string pattern) {
        vector<string> ans;
        for(auto it:words)
        {
            if(match(it,pattern))
                ans.push_back(it);
        }
        return ans;
    }
};

class Solution(object):
    def findAndReplacePattern(self, words, pattern):
        """
        :type words: List[str]
        :type pattern: str
        :rtype: List[str]
        """
        ans = []
        for word in words:
            w2p, p2w = {}, {}
            for w, p in zip(word, pattern):
                if w not in w2p:
                    w2p[w] = p
                elif w2p[w] != p:
                    break
                if p not in p2w:
                    p2w[p] = w
                elif p2w[p] != w:
                    break
            else:
                ans.append(word)
        return ans
